import{_ as a,o as i,c as t,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Claude trend review","description":"","frontmatter":{},"headers":[],"relativePath":"feature/claude-trend-review/spec.md","filePath":"feature/claude-trend-review/spec.md"}'),r={name:"feature/claude-trend-review/spec.md"};function o(s,e,l,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="claude-trend-review" tabindex="-1">Claude trend review <a class="header-anchor" href="#claude-trend-review" aria-label="Permalink to &quot;Claude trend review&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Use Claude API to review new post emotion labels and name T7 trends without altering NER, scoring, membership or stable IDs. Collect corrections for monthly PhoBERT refresh on an existing VM.</p><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h2><ul><li>Reuse current label-check stage; review all new post emotions once per crawl run, in bounded batches. Preserve existing topic selection/seed constraints.</li><li>Preserve original PhoBERT softmax when Claude changes a label; do not invent a 100% probability. Persist correction provenance and training rows.</li><li>T7 receives an optional display_name, naming status and quoted source evidence. keyword/post_ids/scores/IDs remain unchanged. Mixed/insufficient/invalid output keeps the old display fallback.</li><li>Call configured Claude directly, never silently switch providers. Errors/missing key keep the original pipeline output. Reuse valid naming decisions when source content and model are unchanged.</li><li>Persist/display the new name through Neo4j, trend-fit context, chunks and Business-service display mapping; IDs continue to use keyword.</li><li>Provide a calendar-month VM retraining entry point using real corrections plus old replay data, a held-out quality comparison, versioned outputs and no automatic replacement of production adapters. Monthly job installation depends on identifying the existing VM.</li><li>No UI redesign, NER retraining, speculative entity changes, new GPU purchase or deployment.</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Cost/auth follow-up: pin the Anthropic endpoint explicitly, use a separate economical review model, merge emotion batches across platforms, and disable automatic retry/provider fallback for review calls. Naming remains batched and content-cached. S3 testing must use current configured credentials; do not substitute old local data for fresh S3 results.</p><p>CandidateTrend adds optional display_name and name_status. Existing keyword remains the stable source key. All existing fields remain backward-compatible. Emotion probabilities retain their model meaning even if the reviewed label differs.</p><h2 id="failure-behavior" tabindex="-1">Failure behavior <a class="header-anchor" href="#failure-behavior" aria-label="Permalink to &quot;Failure behavior&quot;">​</a></h2><p>Invalid JSON/labels/IDs/citations, missing credentials, model errors or incomplete response cannot overwrite validated values. Uncached failures remain retryable. Training cannot publish a regressing or unvalidated adapter.</p>',10)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
